p {
  color: darkgreen;
  font-size: 18px;
}

#logo { color: navy; }
.note { background-color: lightyellow; }
nav a { text-decoration: none; }

body {
  font-family: Arial, Helvetica, sans-serif;
  font-size: 1.1rem;
  line-height: 1.5;
  text-align: left;
}

.card {
  width: 200px;
  padding: 20px;
  border: 5px solid green;
  margin: 10px;
  background-color: #e8f5e9;
}

* {
  box-sizing: border-box;
}

img {
  max-width: 100%;
  height: auto;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}
.card {
  flex: 1 1 150px;
  padding: 16px;
  background-color: #e3f2fd;
}

.menu {
  display: flex;
  flex-direction: column;
}
@media (min-width: 600px) {
  .menu {
    flex-direction: row;
  }
}

